args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?dir ?deathDate WHERE {
  VALUES ?film { dbr:Kanchana_Sita dbr:Ghost_of_the_China_Sea }
  ?film dbo:director ?dir .
  ?dir dbo:deathDate ?deathDate .
}
ORDER BY ?deathDate
LIMIT 1

